# Pi Coding Agent SDK - Embedding API Reference

## Package Installation

```bash
npm install @earendil-works/pi-coding-agent
```

## Core Import

```typescript
import {
  createAgentSession,
  ModelRuntime,
  SessionManager,
  SettingsManager,
  DefaultResourceLoader,
  getAgentDir
} from "@earendil-works/pi-coding-agent";
```

## Basic Setup

### Minimal Example

```typescript
const modelRuntime = await ModelRuntime.create();
const { session } = await createAgentSession({
  sessionManager: SessionManager.inMemory(),
  modelRuntime,
});
```

### Full Configuration Example

```typescript
import { getModel } from "@earendil-works/pi-ai";

const modelRuntime = await ModelRuntime.create();
const model = getModel("anthropic", "claude-opus-4-5");

const { session } = await createAgentSession({
  // Directory configuration
  cwd: process.cwd(),
  agentDir: getAgentDir(),

  // Model setup
  model,
  thinkingLevel: "medium", // off, minimal, low, medium, high, xhigh, max
  modelRuntime,

  // Tools selection
  tools: ["read", "bash", "edit", "write"], // default tools

  // Session persistence
  sessionManager: SessionManager.inMemory(), // or SessionManager.create(cwd)

  // Settings
  settingsManager: SettingsManager.create(),

  // Custom resource loading
  resourceLoader: loader,
});
```

## createAgentSession Options

### Model Configuration

```typescript
const { session } = await createAgentSession({
  model: getModel("anthropic", "claude-opus-4-5"),
  thinkingLevel: "high",
  scopedModels: [
    { model: opus, thinkingLevel: "high" },
    { model: haiku, thinkingLevel: "off" },
  ],
  modelRuntime,
});
```

### API Key & Authentication

```typescript
// Runtime override (not persisted)
await modelRuntime.setRuntimeApiKey("anthropic", "sk-my-key");

// Check authentication status
const providers = modelRuntime.getProviders();
for (const provider of providers) {
  const status = await modelRuntime.checkAuth(provider.id);
  console.log(provider.name, status);
}

// Custom credential/model paths
const customRuntime = await ModelRuntime.create({
  authPath: "/my/app/auth.json",
  modelsPath: "/my/app/models.json",
});

const { session } = await createAgentSession({
  modelRuntime: customRuntime,
});
```

### Tool Configuration

```typescript
// Built-in tools: read, bash, powershell, edit, write, grep, find, ls
const { session } = await createAgentSession({
  // Read-only mode
  tools: ["read", "grep", "find", "ls"],

  // Or specific selection
  tools: ["read", "bash", "edit", "write"],

  // Disable specific tools
  excludeTools: ["ask_question"],
});
```

### Custom Tools

```typescript
import { Type } from "typebox";
import { defineTool } from "@earendil-works/pi-coding-agent";

const myTool = defineTool({
  name: "my_tool",
  label: "My Tool",
  description: "Does something useful",
  parameters: Type.Object({
    input: Type.String({ description: "Input value" }),
  }),
  execute: async (toolCallId, params) => ({
    content: [{ type: "text", text: `Result: ${params.input}` }],
    details: {},
  }),
});

const { session } = await createAgentSession({
  customTools: [myTool],
  tools: ["read", "bash", "my_tool"],
});
```

### System Prompt & Resource Loader

```typescript
const loader = new DefaultResourceLoader({
  cwd: process.cwd(),
  agentDir: getAgentDir(),
  systemPromptOverride: () => "You are a helpful assistant.",
});
await loader.reload();

const { session } = await createAgentSession({
  resourceLoader: loader,
});
```

### Session Management

```typescript
// In-memory (no persistence)
sessionManager: SessionManager.inMemory()

// Persistent session
sessionManager: SessionManager.create(process.cwd())

// Continue most recent
const { session, modelFallbackMessage } = 
  await createAgentSession({
    sessionManager: SessionManager.continueRecent(process.cwd()),
  });

// Open specific file
sessionManager: SessionManager.open("/path/to/session.jsonl")
```

### Settings Management

```typescript
// From files (global + project merged)
settingsManager: SettingsManager.create()

// With overrides
const settingsManager = SettingsManager.create();
settingsManager.applyOverrides({
  compaction: { enabled: false },
  retry: { enabled: true, maxRetries: 5 },
});

// In-memory (testing)
settingsManager: SettingsManager.inMemory({ 
  compaction: { enabled: false } 
})
```

## Sending Prompts & Awaiting Completion

### Basic Prompt

```typescript
// Basic prompt (when not streaming)
await session.prompt("What files are in the current directory?");

// With images
await session.prompt("What's in this image?", {
  images: [{
    type: "image",
    source: {
      type: "base64",
      mediaType: "image/png",
      data: "..."
    }
  }]
});
```

### During Streaming

```typescript
// Steer: after current tool calls finish
await session.steer("Stop and do this instead");

// Follow up: when agent finishes
await session.followUp("After you're done, also check X");

// Or use streamingBehavior option
await session.prompt("New instruction", {
  streamingBehavior: "steer" // or "followUp"
});
```

### Preflight Notification

```typescript
await session.prompt("Get status", {
  preflightResult: (success) => {
    if (success) console.log("Prompt accepted");
    else console.log("Prompt rejected");
  }
});
```

## Event Subscription

```typescript
session.subscribe((event) => {
  switch (event.type) {
    // Streaming text
    case "message_update":
      if (event.assistantMessageEvent.type === "text_delta") {
        process.stdout.write(event.assistantMessageEvent.delta);
      }
      if (event.assistantMessageEvent.type === "thinking_delta") {
        // Thinking output (if enabled)
      }
      break;

    // Tool execution
    case "tool_execution_start":
      console.log(`Tool: ${event.toolName}`);
      break;
    case "tool_execution_update":
      // Streaming tool output
      break;
    case "tool_execution_end":
      console.log(`Result: ${event.isError ? "error" : "success"}`);
      break;

    // Message lifecycle
    case "message_start":
      break;
    case "message_end":
      break;

    // Agent lifecycle
    case "agent_start":
      break;
    case "agent_end":
      console.log(event.messages); // new messages
      break;

    // Turn lifecycle (LLM response + tool calls)
    case "turn_start":
      break;
    case "turn_end":
      console.log(event.message, event.toolResults);
      break;

    // Session operations
    case "queue_update":
      console.log(event.steering, event.followUp);
      break;
    case "compaction_start":
    case "compaction_end":
    case "auto_retry_start":
    case "auto_retry_end":
      break;
  }
});
```

### Unsubscribe

```typescript
const unsubscribe = session.subscribe((event) => {
  // handle event
});

unsubscribe();
```

## Session State & Control

```typescript
// Access agent state
const state = session.agent.state;
// state.messages, state.model, state.thinkingLevel, state.tools

// Wait for completion
await session.agent.waitForIdle();

// Model control
await session.setModel(newModel);
session.setThinkingLevel("high");
const result = await session.cycleModel();

// Session info
console.log(session.sessionId);
console.log(session.isStreaming);
```

## Cleanup & Disposal

```typescript
// Cleanup resources
session.dispose();

// Flush pending settings writes (before exit)
await settingsManager.flush();

// Abort current operation
await session.abort();

// Abort compaction
session.abortCompaction();
```

## Return Value Structure

```typescript
interface CreateAgentSessionResult {
  session: AgentSession;
  extensionsResult: LoadExtensionsResult;
  modelFallbackMessage?: string;
}
```

## Complete Working Example

```typescript
import { getModel } from "@earendil-works/pi-ai";
import {
  createAgentSession,
  ModelRuntime,
  SessionManager,
} from "@earendil-works/pi-coding-agent";

async function main() {
  const modelRuntime = await ModelRuntime.create();
  const model = getModel("anthropic", "claude-opus-4-5");

  const { session } = await createAgentSession({
    model,
    modelRuntime,
    tools: ["read", "bash"],
    sessionManager: SessionManager.inMemory(),
  });

  // Subscribe to output
  session.subscribe((event) => {
    if (
      event.type === "message_update" &&
      event.assistantMessageEvent.type === "text_delta"
    ) {
      process.stdout.write(event.assistantMessageEvent.delta);
    }
  });

  // Send prompt and wait for completion
  await session.prompt("What files are in the current directory?");

  // Cleanup
  session.dispose();
}

main().catch(console.error);
```

