          const source = pricing[i];
          if (!source) {
            items.push(`${provider.name} pricing: unavailable`);
            return;
          }
          const stale = generatedAt - new Date(source.fetchedAt) > STALE_MS;
          items.push(
            `<a href="${esc(source.sourceUrl)}">${provider.name} pricing</a>: ${esc(fmtDate(source.fetchedAt))}` +
              (stale ? '<span class="badge">stale</span>' : ""),
          );
        });
        document.getElementById("meta").innerHTML = items.map((i) => `<span>${i}</span>`).join("");
      }

      function renderTable(rows) {
        if (!rows?.length) return '<p class="empty">No scored models.</p>';
        const body = rows
          .map(
            (r, i) => `<tr>
              <td>${i + 1}</td>
              <td class="model">${esc(r.model)}</td>
              <td class="score">${num(r.score, 3)}</td>
              <td>${num(r.breakdown.agenticIndex)}</td>
              <td>${num(r.breakdown.codingIndex)}</td>
              <td>${num(r.breakdown.intelligenceIndex)}</td>
              <td>${num(r.breakdown.speed, 0)}</td>
              <td>$${num(r.priceBlendedPer1M, 3)}</td>
            </tr>`,
          )
          .join("");
        return `<div class="table-wrap"><table>
          <thead><tr>
            <th>#</th><th>Model</th><th>Score</th><th>Agentic</th><th>Coding</th>
            <th>Intel.</th><th>Tok/s</th><th>$/1M</th>
          </tr></thead>
          <tbody>${body}</tbody>
        </table></div>`;
      }

      function renderCategory(name, byProvider, config) {
        const weights = Object.entries(config?.weights ?? {})
          .filter(([, w]) => w > 0)
          .sort((a, b) => b[1] - a[1])
          .map(([k, w]) => `<li>${esc(WEIGHT_LABELS[k] ?? k)} ${Math.round(w * 100)}%</li>`)
          .join("");
        const providers = PROVIDERS.map(
          (p) => `<div><h3>${p.name}</h3>${renderTable(byProvider[p.id])}</div>`,
        ).join("");
        return `<section class="category">
          <h2>${esc(titleCase(name))}</h2>
          ${config?.description ? `<p class="desc">${esc(config.description)}</p>` : ""}
          <ul class="weights">${weights}</ul>
          <div class="providers">${providers}</div>
        </section>`;
      }

      async function main() {
        const app = document.getElementById("app");
        try {
          const [recs, config, ...pricing] = await Promise.all([
            getJson("data/recommendations.json"),
            getJson("categories.json").catch(() => ({ categories: {} })),
            ...PROVIDERS.map((p) => getJson(`data/${p.id}/models-pricing.json`).catch(() => null)),
          ]);
          renderMeta(recs, pricing);
          app.innerHTML = Object.entries(recs.categories)
            .map(([name, byProvider]) => renderCategory(name, byProvider, config.categories[name]))
            .join("");
        } catch (err) {
          app.innerHTML = `<p class="error">Could not load recommendations (${esc(err.message)}).</p>`;
        }
      }

      main();
    </script>
  </body>
</html>

