      `[${source.id}] Pi repair gave up after ${MAX_ATTEMPTS} attempts; keeping existing ${source.outFile}. ` +
        `Pi's last attempt is left in ${relative(source.parserPath)} (see git diff).`,
    );
    return null;
  } finally {
